/*Adrian Sullivan - 2026/05/21  SSMS spatial-tab palette lookup.
Loads the 4096 singleton colours + 64 overlap-pair composites sampled
via extract-palette.ps1 into dbo.SsmsPaletteRecipe, then exposes:
  dbo.fn_SsmsPaletteColour(@row_idx INT) RETURNS CHAR(7)
  dbo.fn_NearestSsmsRecipe(@target_hex CHAR(7)) RETURNS TABLE
Re-running drops and recreates everything.*/

IF OBJECT_ID('dbo.fn_NearestSsmsRecipe') IS NOT NULL DROP FUNCTION dbo.fn_NearestSsmsRecipe;
IF OBJECT_ID('dbo.fn_SsmsPaletteColour')  IS NOT NULL DROP FUNCTION dbo.fn_SsmsPaletteColour;
IF OBJECT_ID('dbo.SsmsPaletteRecipe')     IS NOT NULL DROP TABLE   dbo.SsmsPaletteRecipe;
GO

CREATE TABLE dbo.SsmsPaletteRecipe (
    recipe_id  INT IDENTITY(1,1) PRIMARY KEY,
    R          TINYINT     NOT NULL,
    G          TINYINT     NOT NULL,
    B          TINYINT     NOT NULL,
    hex        CHAR(7)     NOT NULL,
    kind       VARCHAR(16) NOT NULL,   --singleton | overlap_pair
    row_idx_1  INT         NOT NULL,   --bottom or only
    row_idx_2  INT         NULL        --top if overlap_pair
);
CREATE INDEX IX_SsmsPaletteRecipe_rgb ON dbo.SsmsPaletteRecipe (R, G, B);
GO

