/*lookup singleton hex by row idx.  returns NULL outside 1..N.*/
CREATE FUNCTION dbo.fn_SsmsPaletteColour(@row_idx INT)
RETURNS CHAR(7)
AS
BEGIN
    DECLARE @hex CHAR(7);
    SELECT @hex = hex
    FROM dbo.SsmsPaletteRecipe
    WHERE kind = 'singleton' AND row_idx_1 = @row_idx;
    RETURN @hex;
END
GO

/*nearest-recipe lookup.  squared euclidean distance in RGB.
@target_hex accepts '#rrggbb' or 'rrggbb' (case-insensitive).
Returns one row with recipe_id, kind, row_idx_1, row_idx_2, the recipe's
R/G/B/hex, and squared distance to the target so callers can threshold.*/
CREATE FUNCTION dbo.fn_NearestSsmsRecipe(@target_hex VARCHAR(8))
RETURNS TABLE
AS
RETURN (
    WITH norm AS (
        SELECT CASE WHEN LEFT(@target_hex, 1) = '#'
                    THEN SUBSTRING(@target_hex, 2, 6)
                    ELSE @target_hex END AS h
        WHERE @target_hex IS NOT NULL AND LEN(@target_hex) >= 6
    ),
    t AS (
        SELECT
            CAST(CONVERT(VARBINARY(1), SUBSTRING(n.h, 1, 2), 2) AS INT) AS tr,
            CAST(CONVERT(VARBINARY(1), SUBSTRING(n.h, 3, 2), 2) AS INT) AS tg,
            CAST(CONVERT(VARBINARY(1), SUBSTRING(n.h, 5, 2), 2) AS INT) AS tb
        FROM norm n
    )
    SELECT TOP 1
        r.recipe_id, r.kind, r.row_idx_1, r.row_idx_2,
        r.R, r.G, r.B, r.hex,
        POWER(CAST(r.R - t.tr AS FLOAT), 2) +
        POWER(CAST(r.G - t.tg AS FLOAT), 2) +
        POWER(CAST(r.B - t.tb AS FLOAT), 2) AS distance_sq
    FROM dbo.SsmsPaletteRecipe r
    CROSS JOIN t
    ORDER BY POWER(CAST(r.R - t.tr AS FLOAT), 2) +
             POWER(CAST(r.G - t.tg AS FLOAT), 2) +
             POWER(CAST(r.B - t.tb AS FLOAT), 2)
);
GO

